"""Build the four documents in docs/ from a campaign run.

    python tools/build_docs.py --campaign output/campaign_out            # all four
    python tools/build_docs.py --campaign output/campaign_out --only explainer,invariance

Where each document comes from:

* ``ANSWER_SHEET.html`` — generated by ``tools/answer_sheet.py`` from the trained store and the
  campaign's dataset (every case: customer turn, meaning card, required acts and tool calls).
* ``ANNOTATED.html`` — generated by ``tools/build_annotated.py`` from the three source files,
  with a captured trace embedded.
* ``EXPLAINER.html`` and ``INVARIANCE.html`` — the two written pages. Their headline figures are
  filled from ``tools/templates/*.html`` with this run's numbers out of ``report.json``, so the
  tiles always describe the campaign you just ran. Their worked examples (the J000 walkthrough,
  the near-miss trace, the signature strings) are a specific run's, and the stamp at the top of
  the tiles says which.

Edit the templates, never ``docs/*.html`` — this script overwrites those.
"""
from __future__ import annotations

import argparse
import json
import subprocess
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TEMPLATES = ROOT / "tools" / "templates"


def num(v) -> str:
    return f"{int(v):,}" if float(v).is_integer() else f"{v:,.1f}"


def pct(v) -> str:
    return f"{100 * float(v):.1f}%"


def context(campaign: Path, report: dict) -> dict[str, str]:
    """The slot values both written pages are filled with, all read from this run's report."""
    inv, res = report["invariance"]["summary"], report["results"]
    llm = report.get("invariance_llm") or {}
    ls = llm.get("summary") or {}
    nc = (llm.get("negative_controls") or {}).get("_overall") or {}
    adv = (llm.get("negative_controls") or {}).get("_adversarial") or {}
    gates = ls.get("gate_failures_by_attempt") or {}
    ctrl_n = report["invariance"]["negative_controls"]["_overall"]["n"]

    policy = Path(report["config"]["policy_path"])
    triples = len(json.loads(policy.read_text(encoding="utf-8"))["triples"]) if policy.exists() else "?"
    resilience = report.get("resilience") or []
    silent = sum(f.get("silent", 0) for f in resilience) if isinstance(resilience, list) else 0
    written = time.strftime("%Y-%m-%d %H:%M", time.localtime((campaign / "report.json").stat().st_mtime))
    try:
        where = campaign.relative_to(ROOT).as_posix()
    except ValueError:
        where = campaign.as_posix()

    return {
        "POLICY_TRIPLES": num(triples),
        "SCENARIOS": num(inv["scenarios"]),
        "PROVED": num(inv["accepted"]),
        "TURNS": num(inv["turns_checked"]),
        "ACC_BASE": pct(res["base_level"]["accuracy"]),
        "ACC_ENRICHED": pct(res["enriched"]["accuracy"]),
        "LLM_MATERIALISED": num(ls.get("accepted", 0)),
        "MEAN_ATTEMPTS": f"{float(ls.get('mean_attempts_per_turn') or 0):.2f}",
        "DUAL_AGREEMENT": pct((ls.get("dual_read") or {}).get("agreement") or 0),
        "DUAL_FAILS": num(gates.get("G2_dual_read", 0)),
        "GATE_FAILS": num(sum(gates.values())),
        "CONTROLS_N": num(ctrl_n),
        "LLM_CONTROLS_N": num(nc.get("n", 0)),
        "LLM_CONTROLS_OK": num(round(nc.get("n", 0) * nc.get("detection_rate", 0))),
        "LLM_CONTROLS_RATE": pct(nc.get("detection_rate", 0)),
        "ADV_N": num(adv.get("n", 0)),
        "ADV_EFFECTIVE": num(adv.get("effective", 0)),
        "MUTATION_COMBINED": pct(report["mutation"]["mutation_score"]["all_suites_combined"]),
        "SILENT_FAILURES": num(silent),
        "CAMPAIGN_DIR": where,
        "RUN_STAMP": (f"Generated from the campaign in <code>{where}</code> — report written {written}, "
                      f"{report['backend'].get('selected')} backend, {num(inv['scenarios'])} scenarios, "
                      f"{num(report.get('elapsed_seconds') or 0)} s — by <code>tools/build_docs.py</code>."),
    }


def fill(template: Path, ctx: dict[str, str], out: Path) -> list[str]:
    """Every {{SLOT}} in the template gets a value; unknown slots are reported, not left silent."""
    s = template.read_text(encoding="utf-8")
    missing = []
    for key, value in ctx.items():
        s = s.replace("{{" + key + "}}", value)
    for leftover in sorted(set(__import__("re").findall(r"\{\{([A-Z_]+)\}\}", s))):
        missing.append(leftover)
    out.write_text(s, encoding="utf-8")
    return missing


def run_tool(name: str, args: list[str]) -> bool:
    print(f"  {name} …", flush=True)
    r = subprocess.run([sys.executable, str(ROOT / "tools" / name), *args],
                       capture_output=True, text=True, cwd=str(ROOT))
    tail = (r.stdout or r.stderr or "").strip().splitlines()[-1:] or [""]
    print(f"    {'ok' if r.returncode == 0 else 'FAILED'}: {tail[0][:110]}", flush=True)
    if r.returncode != 0:
        print((r.stderr or "")[-600:], flush=True)
    return r.returncode == 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--campaign", default="output/campaign_out", help="the run to describe")
    ap.add_argument("--out", default="docs", help="where the four documents are written")
    ap.add_argument("--store-dir", default=None, help="passed to answer_sheet (default: the build cache)")
    ap.add_argument("--trace", default=str(TEMPLATES / "annotated_trace.txt"),
                    help="trace embedded in ANNOTATED.html (omit with --trace none)")
    ap.add_argument("--summaries", default="template", choices=["template", "llm"],
                    help="answer sheet: llm adds a checked model-written summary to every case")
    ap.add_argument("--only", default="answer_sheet,annotated,explainer,invariance",
                    help="comma-separated subset to build")
    a = ap.parse_args()

    campaign, out = Path(a.campaign), Path(a.out)
    out.mkdir(parents=True, exist_ok=True)
    if not (campaign / "report.json").exists():
        print(f"no report.json in {campaign} — run a campaign first (see README)")
        return 1
    report = json.loads((campaign / "report.json").read_text(encoding="utf-8"))
    ctx = context(campaign, report)
    want = {w.strip() for w in a.only.split(",") if w.strip()}
    ok = True

    if "answer_sheet" in want:
        args = ["--campaign", str(campaign), "--out", str(out / "ANSWER_SHEET.html")]
        if a.store_dir:
            args += ["--store-dir", a.store_dir]
        args += ["--summaries", a.summaries]
        ok &= run_tool("answer_sheet.py", args)

    if "annotated" in want:
        args = ["--out", str(out / "ANNOTATED.html")]
        if a.trace and a.trace != "none" and Path(a.trace).exists():
            args += ["--trace", a.trace]
        ok &= run_tool("build_annotated.py", args)

    for key, name in (("explainer", "EXPLAINER.html"), ("invariance", "INVARIANCE.html")):
        if key not in want:
            continue
        src, dst = TEMPLATES / name, out / name
        missing = fill(src, ctx, dst)
        print(f"  {name}: filled from {src.relative_to(ROOT).as_posix()}"
              + (f"  !! unfilled slots: {missing}" if missing else ""))
        ok &= not missing

    try:
        shown = out.relative_to(ROOT).as_posix()
    except ValueError:
        shown = out.as_posix()
    print(f"\n{len(want)} document(s) in {shown}/ — from the run in "
          f"{ctx['CAMPAIGN_DIR']} ({ctx['SCENARIOS']} scenarios, {ctx['ACC_BASE']} → {ctx['ACC_ENRICHED']})")
    return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main())
